<?php
declare(strict_types=1);
require_once __DIR__.'/annual-selection.php';
function annualApi(array $u,string $action,string $method,array $b):array{fullManager($u);$t=$u['tenant'];
 if($action==='overview')return ['ordinances'=>records($t,'ordinances'),'eligibility'=>records($t,'eligibility'),'batches'=>records($t,'batches')];
 if($action==='ordinances')return ['id'=>saveAnnualOrdinance($u,$b)['id']];
 if($action==='finalize')return finalizeAnnualSelection($u,$b);
 if($action==='qualify'){$p=linkFor($u,$b['linkId']??'');$plan=record($t,'plans',$p['planId']);if($plan['family']!=='geral')throw new Fault('O Magistério e o Legislativo possuem regras próprias.');$cycle=(int)($b['cycle']??0);if($cycle<2000||$cycle>2200||$cycle.'-06-30'>today())throw new Fault('O fechamento aquisitivo ainda não ocorreu.');if(($b['checks']??[])!==[true,true,true,true,true]||$p['version']!==($b['version']??null))throw new Fault('Conclua as conferências sobre a versão atual da matrícula.');$x=null;foreach($p['processes'] as $proc)if($proc['id']===($b['processId']??'')&&$proc['state']==='Em análise')$x=$proc;if(!$x||$x['end']>$cycle.'-06-30'||$p['probation']!=='Concluído')throw new Fault('Processo, estabilidade ou período aquisitivo incompatíveis.');foreach($p['paidFunctions']??[] as $a)if($a['start']<=$x['end']&&(!$a['end']||$a['end']>=$x['start'])&&in_array($a['careerEffect'],['unreviewed','suspend','special']))throw new Fault('A função exige apuração específica do tempo e do efeito antes da habilitação.');$proof=eligibleProof($t,$p,$x,$cycle);$rules=array_values(array_filter(records($t,'rules'),fn($r)=>$r['plan']===$p['planId']));$familyRules=$rules[0]['config']??null;if($familyRules&&$x['type']==='Progressão horizontal'&&array_sum(array_column($proof,'hours'))<$familyRules['hours'])throw new Fault('Certificados aprovados, não consumidos e enviados até 30/06 não atingem as horas exigidas.');if($x['type']==='Promoção vertical'&&!$proof)throw new Fault('Falta titulação aprovada compatível com o destino.');$existing=null;foreach(records($t,'eligibility') as $e)if($e['link']===$p['id']&&$e['process']===$x['id'])$existing=$e;if($existing['batch']??null)throw new Fault('Processo já concedido.');$r=save($t,'eligibility',['id'=>$existing['id']??uid(),'link'=>$p['id'],'process'=>$x['id'],'cycle'=>$cycle,'version'=>$p['version'],'linkVersion'=>$p['version'],'reason'=>need($b['reason']??'','fundamentação',2000),'evidence'=>$proof,'actor'=>$u['id'],'created'=>date(DATE_ATOM),'batch'=>null]);audit($t,'annual.qualify',$p['id']);return ['id'=>$r['id']];}
 if($action==='rank')return ['rows'=>rankAnnual($u,$b['plan']??'',(int)($b['cycle']??0),$b['criteria']??[])];
 if($action==='budget'||$action==='grant'){$o=record($t,'ordinances',$b['ordinanceId']??'');if(!$o&&$action==='budget')$o=annualPreview($u,$b);if(!$o)throw new Fault('Portaria não encontrada.');$rank=rankAnnual($u,$o['plan'],$o['cycle'],$b['criteria']??[]);$ids=$b['eligibilityIds']??[];$excluded=validateSelection($rank,$ids);$budget=annualBudget($u,$ids,$o,$b['budgetOptions']??[]);if($action==='budget')return $budget;if(($b['confirmed']??false)!==true)throw new Fault('Confirme a conferência do lote.');$basis=need($b['basis']??'','fundamento dos critérios',2000);$reason=$excluded?need($b['omissionReason']??'','justificativa dos não incluídos',2000):null;$omission=$excluded?need($b['omissionBasis']??'','dispositivo autorizador da não inclusão',2000):null;if(!$budget['complete'])throw new Fault('Existem pendências de cálculo salarial.');if(!hash_equals($budget['token'],(string)($b['budgetToken']??'')))throw new Fault('Recalcule o orçamento da seleção atual.',409);$id=uid();$selected=[];foreach($rank as $r)if(in_array($r['id'],$ids,true)){$p=record($t,'links',$r['link']);$e=record($t,'eligibility',$r['id']);$idx=array_search($e['process'],array_column($p['processes'],'id'),true);$x=&$p['processes'][$idx];$future=$o['effect']>today();$x['state']=$future?'Aprovado · efeito futuro':'Aprovado';$x['reason']=$e['reason'];$x['act']=$o['number'];$x['effect']=$o['effect'];$x['batch']=$id;$x['decidedBy']=$u['id'];$x['evidence']=$e['evidence'];if(!$future){$p['level']=$x['targetLevel'];$p['stage']=$x['targetStage'];$p['enrollmentDate']=$o['effect'];$p['enrollmentAct']=$o['number'];if(isset($x['salaryTarget']))$p['salary']=array_replace($x['salaryTarget'],['context'=>salaryContextKey($p),'target'=>null]);}$p['status']=$future?'Concessão futura':'Regular';unset($x);event($p,$u,'Progressão concedida por portaria',$o['number'].' · efeito '.$o['effect']);updateLink($u,$p,$p['version'],'annual.grant');$e['batch']=$id;save($t,'eligibility',$e);$selected[]=$r;}$batch=save($t,'batches',['id'=>$id,'ordinance'=>$o['id'],'criteria'=>$b['criteria'],'basis'=>$basis,'omission_reason'=>$reason,'omission_basis'=>$omission,'selected'=>$selected,'excluded'=>$excluded,'budget'=>$budget,'expected'=>count($selected),'applied'=>count($selected),'actor'=>$u['id'],'created'=>date(DATE_ATOM)]);audit($t,'annual.batch',$id);return ['id'=>$id,'count'=>count($selected),'effect'=>$o['effect']];}
 if($action==='activate'){$p=linkFor($u,$b['linkId']??'');$idx=array_search($b['processId']??'',array_column($p['processes'],'id'),true);if($idx===false)throw new Fault('Processo não encontrado.');$x=&$p['processes'][$idx];if($x['state']!=='Aprovado · efeito futuro'||$x['effect']>today()||$p['level']!==$x['fromLevel']||$p['stage']!==$x['fromStage'])throw new Fault('Vigência ainda não iniciada ou enquadramento alterado.');$p['level']=$x['targetLevel'];$p['stage']=$x['targetStage'];$p['enrollmentDate']=$x['effect'];$p['enrollmentAct']=$x['act'];$p['status']='Regular';$x['state']='Aprovado';if(isset($x['salaryTarget']))$p['salary']=array_replace($x['salaryTarget'],['context'=>salaryContextKey($p),'target'=>null]);unset($x);event($p,$u,'Efeito da portaria aplicado',$p['enrollmentAct']);updateLink($u,$p,(int)($b['version']??0),'annual.activate');return ['ok'=>true];}
 throw new Fault('Recurso anual não encontrado.',404);
}
